require_once __DIR__.'/bootstrap.php';require QA_ROOT.'/config/database.php';require __DIR__.'/support/account_tables.php';ini_set('error_log',QA_CASE_DIR.'/expected-failure.log');require QA_ROOT.'/classes/examinations/ExamBooking.php';
$db=(new Database)->getConnection();foreach(['users','student_profiles','academic_departments','academic_grade_levels','system_settings','entrance_exam_appointments','entrance_exam_daily_limits','schedules','holidays','school_closures','notifications','email_outbox','system_logs'] as $t)accountTemporaryTable($db,$t);
$db->exec("INSERT INTO users(id,role,email,first_name,last_name,is_active,archived,grade_level_applying,examinee_type) VALUES(99101,'examinee','one@example.invalid','Synthetic','One',1,0,NULL,'Transferee'),(99102,'examinee','two@example.invalid','Synthetic','Two',1,0,'Grade 11','Transferee'),(99103,'student','student@example.invalid','Synthetic','Student',1,0,NULL,NULL),(99104,'examinee','inactive@example.invalid','Synthetic','Inactive',0,0,NULL,NULL),(99105,'examinee','new@example.invalid','Synthetic','New',1,0,NULL,'New Student'),(99106,'examinee','rollback@example.invalid','Synthetic','Rollback',1,0,NULL,'Transferee');INSERT INTO academic_departments(id,name,is_active) VALUES(1,'Active school',1),(2,'Closed department',0);INSERT INTO academic_grade_levels(department_id,name,is_active,sort_order) VALUES(1,'Grade 11',1,1),(1,'Grade 4',1,2),(1,'Grade 9',0,3),(2,'Grade 8',1,4);INSERT INTO system_settings(setting_key,setting_value) VALUES('entrance_exam_enabled',1)");$date=(new DateTimeImmutable('tomorrow'))->modify('next Monday')->format('Y-m-d');$db->prepare("INSERT INTO schedules(id,title,event_type,start_datetime,end_datetime,is_active,created_by) VALUES(1,'Synthetic exam','entrance_exam',?,?,1,99102)")->execute([$date.' 08:00:00',$date.' 17:00:00']);$b=new ExamBooking($db);$checks=[];function ok($n,$v){global $checks;if(!$v)throw new RuntimeException($n);$checks[]=$n;}function deny($n,$fn){$e=null;try{$fn();}catch(Throwable $caught){$e=$caught;}ok($n,(bool)$e);}function grade($uid){global $db;return $db->query('SELECT grade_level_applying FROM users WHERE id='.(int)$uid)->fetchColumn();}
ok('Blank applicant grade is detected before booking',$b->applicantContext(99101)['grade']===''&&!$b->applicantContext(99101)['locked']);ok('Only active school choices are offered',$b->gradeOptions()===['Grade 11','Grade 4']);ok('New student choices retain the registration entry-level rules',$b->gradeOptions('New Student')===['Grade 11']);deny('Blank inline choice is rejected',fn()=>$b->book(99101,$date,'08:00:00','Synthetic school',null,1,''));deny('Inactive grade is rejected',fn()=>$b->updateApplicantGrade(99101,'Grade 9'));deny('Inactive department is rejected',fn()=>$b->updateApplicantGrade(99101,'Grade 8'));deny('Unexpected array input is rejected',fn()=>$b->updateApplicantGrade(99101,['Grade 11']));deny('Student cannot edit official academics through applicant endpoint',fn()=>$b->updateApplicantGrade(99103,'Grade 11'));deny('Inactive account cannot edit applicant level',fn()=>$b->updateApplicantGrade(99104,'Grade 11'));deny('New student cannot bypass entry-level rule',fn()=>$b->updateApplicantGrade(99105,'Grade 4'));
$id=$b->book(99101,$date,'08:00:00','Synthetic school',null,1,'Grade 4');ok('Legacy account can choose a valid level while booking',grade(99101)==='Grade 4');ok('Booked exam records the selected level',$db->query('SELECT grade_level_applying FROM entrance_exam_appointments WHERE id='.(int)$id)->fetchColumn()==='Grade 4');ok('An active booking locks self-service level changes',$b->applicantContext(99101)['locked']);deny('Active booking cannot have a conflicting profile grade',fn()=>$b->updateApplicantGrade(99101,'Grade 11'));
ok('Examinee can correct grade before booking',$b->updateApplicantGrade(99102,'Grade 4')==='Grade 4');ok('Changing back before booking works',$b->updateApplicantGrade(99102,'Grade 11')==='Grade 11');ok('No student profile is assigned or changed',(int)$db->query('SELECT COUNT(*) FROM student_profiles')->fetchColumn()===0);deny('Booking cannot silently replace an existing applicant level',fn()=>$b->book(99102,$date,'08:00:00','Synthetic school',null,1,'Grade 4'));ok('Failed booking preserves existing grade',grade(99102)==='Grade 11');$b->book(99102,$date,'08:00:00','Synthetic school');$db->exec("UPDATE entrance_exam_appointments SET status='completed',exam_result='passed' WHERE user_id=99102");deny('Released results remain protected from self-service changes',fn()=>$b->updateApplicantGrade(99102,'Grade 4'));$db->exec("UPDATE entrance_exam_appointments SET status='cancelled' WHERE user_id=99101");ok('Cancelled booking releases applicant-level editing',$b->updateApplicantGrade(99101,'Grade 11')==='Grade 11');$db->exec("UPDATE entrance_exam_appointments SET status='missed',reschedule_pending=1 WHERE user_id=99101");deny('Waiting automatic replacement keeps the applied grade locked',fn()=>$b->updateApplicantGrade(99101,'Grade 4'));
$db->exec("ALTER TABLE entrance_exam_appointments MODIFY status VARCHAR(30);UPDATE entrance_exam_appointments SET status='rescheduled',reschedule_pending=0 WHERE user_id=99101");ok('Legacy rescheduled status stays locked',$b->applicantContext(99101)['locked']);deny('Legacy replacement application cannot be changed',fn()=>$b->updateApplicantGrade(99101,'Grade 4'));
$db->exec('DELETE FROM notifications;DELETE FROM email_outbox;ALTER TABLE notifications ADD CONSTRAINT reject_grade_fixture CHECK(user_id=0)');deny('Notification failure aborts the booking',fn()=>$b->book(99106,$date,'08:00:00','Synthetic school',null,1,'Grade 11'));ok('Failed booking rolls back newly supplied account grade',grade(99106)===null);ok('Failed booking leaves no appointment',(int)$db->query('SELECT COUNT(*) FROM entrance_exam_appointments WHERE user_id=99106')->fetchColumn()===0);
file_put_contents(QA_RESULTS.'/Applicant-Grade-Checks.json',json_encode($checks,JSON_PRETTY_PRINT));echo count($checks)." applicant-grade, role, booking, history and rollback checks passed using temporary records.\n";
